from version_compare import latest_version, meets_minimum


def newest_compatible(versions: list[str], minimum: str) -> str | None:
    """Return the highest version in `versions` that is at least `minimum`, or None if none qualify."""
    compatible = [v for v in versions if meets_minimum(v, minimum)]
    return latest_version(compatible)

import asyncio
from async_bridge import run_sync


def run_with_deadline(coros: list, seconds: float) -> list:
    """Run coroutines concurrently, returning results in input order.
    Coroutines not finished within `seconds` are cancelled and replaced by None.
    Can be called repeatedly from synchronous code with no running event loop."""
    async def _main():
        tasks = [asyncio.create_task(c) for c in coros]
        done, pending = await asyncio.wait(tasks, timeout=seconds)
        # Cancel all pending tasks
        for task in pending:
            task.cancel()
        # Await cancellation completion
        await asyncio.gather(*pending, return_exceptions=True)
        results = []
        for task in tasks:
            if task in done:
                try:
                    results.append(task.result())
                except Exception:
                    # Propagate exceptions from finished tasks
                    raise
            else:
                results.append(None)
        return results

    return run_sync(_main())

from packaging.version import Version


def newest_compatible(versions: list[str], minimum: str) -> str | None:
    min_ver = Version(minimum)
    best_version = None
    best_version_obj = None
    for v in versions:
        try:
            ver_obj = Version(v)
        except Exception:
            # Ignore invalid version strings
            continue
        if ver_obj >= min_ver:
            if best_version_obj is None or ver_obj > best_version_obj:
                best_version_obj = ver_obj
                best_version = v
    return best_version

import asyncio
from typing import List, Optional, Coroutine


def run_with_deadline(coros: List[Coroutine], seconds: float) -> List[Optional[object]]:
    """
    Run the given coroutines concurrently with a timeout deadline.
    Return a list of results in input order.
    For any coroutine not finished within `seconds`, cancel it and return None in its place.

    This function can be called repeatedly in the same process.
    """
    async def _run_all_with_deadline(coros, timeout):
        tasks = [asyncio.create_task(coro) for coro in coros]
        done, pending = await asyncio.wait(tasks, timeout=timeout)
        results = [None] * len(tasks)
        # Cancel pending tasks
        for task in pending:
            task.cancel()
        # Await cancellation completion
        for task in pending:
            try:
                await task
            except asyncio.CancelledError:
                pass
            except Exception:
                # Ignore exceptions from cancelled tasks
                pass
        # Collect results from done tasks
        for i, task in enumerate(tasks):
            if task in done:
                try:
                    results[i] = task.result()
                except Exception:
                    # If a task raised an exception, propagate it
                    raise
        return results

    return asyncio.run(_run_all_with_deadline(coros, seconds))
